using System;using System.IO;using System.Linq;using System.Text;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;
[InitializeOnLoad]public static class CoastalMountainDetails{
const string Dir="Assets/Scenes/Oasis/CoastalTerrain/Details";static BindingFlags F=BindingFlags.Static|BindingFlags.NonPublic;static System.Random rng=new System.Random(7341);
static float R(float a,float b)=>(float)(a+rng.NextDouble()*(b-a));static CoastalMountainDetails(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("CoastalMountainDetails.request")||EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode)return;File.Delete("CoastalMountainDetails.request");Run();}
class Geo{public List<Vector3> p=new List<Vector3>();public List<Vector2> uv=new List<Vector2>();public List<int> t=new List<int>();public void Tri(Vector3 a,Vector3 b,Vector3 c){int n=p.Count;p.AddRange(new[]{a,b,c});uv.AddRange(new[]{new Vector2(a.x,a.z),new Vector2(b.x,b.z),new Vector2(c.x,c.z)});t.AddRange(new[]{n,n+1,n+2});}public Mesh Make(string name){var m=new Mesh{name=name,indexFormat=IndexFormat.UInt32};m.SetVertices(p);m.SetUVs(0,uv);m.SetTriangles(t,0);m.RecalculateNormals();m.RecalculateBounds();return m;}}
static void Cone(Geo g,Vector3 center,float radius,float height,int sides,int seed){var tip=center+Vector3.up*height;for(int j=0;j<sides;j++){float a=j*2*Mathf.PI/sides,b=(j+1)*2*Mathf.PI/sides;float r0=radius*(.85f+.15f*Mathf.Sin(j*7+seed)),r1=radius*(.85f+.15f*Mathf.Sin((j+1)*7+seed));var p=center+new Vector3(Mathf.Cos(a)*r0,0,Mathf.Sin(a)*r0);var q=center+new Vector3(Mathf.Cos(b)*r1,0,Mathf.Sin(b)*r1);g.Tri(q,p,tip);g.Tri(p,q,center-Vector3.up*.13f);}}
static Mesh Cards(bool far,int variant,bool tree){var g=new Geo();int planes=far?2:3;float width=tree?(variant==1?3.8f:4.8f):2.8f;float height=tree?9.2f:1.8f;int tile=variant%2;float u0=tile==0?.005f:.55f,u1=tile==0?.525f:.995f;float v0=tree?.32f:.005f,v1=tree?.995f:.31f;for(int i=0;i<planes;i++){var rotation=Quaternion.Euler(0,i*180f/planes,0);int n=g.p.Count;g.p.AddRange(new[]{rotation*new Vector3(-width/2,0,0),rotation*new Vector3(width/2,0,0),rotation*new Vector3(-width/2,height,0),rotation*new Vector3(width/2,height,0)});g.uv.AddRange(new[]{new Vector2(u0,v0),new Vector2(u1,v0),new Vector2(u0,v1),new Vector2(u1,v1)});g.t.AddRange(new[]{n,n+2,n+1,n+1,n+2,n+3});}return g.Make((tree?"Textured Pine ":"Textured Shrub ")+variant+(far?" distant":" near"));}
static Mesh Pine(bool far,int variant)=>Cards(far,variant,true);
static Mesh Shrub(bool far,int variant)=>Cards(far,variant,false);
static Material Foliage(string name,Color color,Texture texture){var m=Mat(name,color,texture);m.shader=AssetDatabase.LoadAssetAtPath<Shader>(Dir+"/MobileMountainFoliage.shader");m.SetTexture("_Atlas",texture);m.SetColor("_Tint",color);m.SetFloat("_AlphaClip",1);m.EnableKeyword("_ALPHATEST_ON");m.SetFloat("_Cutoff",.38f);m.SetFloat("_Cull",0);m.SetOverrideTag("RenderType","TransparentCutout");m.renderQueue=2450;EditorUtility.SetDirty(m);return m;}
static void ConfigureAtlas(){var path=Dir+"/Mountain Foliage Atlas.png";var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.alphaIsTransparency=true;importer.mipmapEnabled=true;importer.mipMapsPreserveCoverage=true;importer.alphaTestReferenceValue=.38f;importer.streamingMipmaps=true;importer.wrapMode=TextureWrapMode.Clamp;importer.filterMode=FilterMode.Trilinear;importer.anisoLevel=2;importer.maxTextureSize=2048;foreach(string platform in new[]{"Android","iPhone"})importer.SetPlatformTextureSettings(new TextureImporterPlatformSettings{name=platform,overridden=true,maxTextureSize=2048,format=TextureImporterFormat.ASTC_6x6,compressionQuality=85});importer.SaveAndReimport();}
static Mesh Trunk(){var g=new Geo();Cone(g,Vector3.zero,.17f,9.1f,6,0);return g.Make("Six sided mountain pine trunk");}
static Mesh SaveMesh(Mesh m,string path){var existing=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(existing){existing.Clear();existing.indexFormat=m.indexFormat;existing.vertices=m.vertices;existing.triangles=m.triangles;existing.uv=m.uv;existing.normals=m.normals;existing.RecalculateBounds();UnityEngine.Object.DestroyImmediate(m);EditorUtility.SetDirty(existing);return existing;}AssetDatabase.CreateAsset(m,path);return m;}
static Material Mat(string name,Color color,Texture texture){string path=Dir+"/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.name=name;m.SetColor("_BaseColor",color);m.SetTexture("_BaseMap",texture);m.SetFloat("_Smoothness",.05f);m.enableInstancing=true;EditorUtility.SetDirty(m);return m;}
class Batch{public List<CombineInstance> near=new List<CombineInstance>();public List<CombineInstance> far=new List<CombineInstance>();}
static void Add(Dictionary<string,Batch> batches,string type,int x,int z,Mesh near,Mesh far,Matrix4x4 matrix){string key=type+"_"+x+"_"+z;if(!batches.TryGetValue(key,out var b)){b=new Batch();batches.Add(key,b);}b.near.Add(new CombineInstance{mesh=near,transform=matrix});b.far.Add(new CombineInstance{mesh=far,transform=matrix});}
static Mesh Combined(List<CombineInstance> list,string name){var m=new Mesh{name=name,indexFormat=IndexFormat.UInt32};m.CombineMeshes(list.ToArray(),true,true);return m;}
static Renderer Child(GameObject parent,string name,Mesh mesh,Material material){var g=new GameObject(name);g.transform.SetParent(parent.transform,false);g.AddComponent<MeshFilter>().sharedMesh=mesh;var renderer=g.AddComponent<MeshRenderer>();renderer.sharedMaterial=material;renderer.shadowCastingMode=ShadowCastingMode.On;renderer.receiveShadows=true;return renderer;}
static Mesh Cluster(Mesh input,float cells,string name){var points=input.vertices;var source=input.triangles;var map=new Dictionary<Vector3Int,int>();var vertices=new List<Vector3>();var remap=new int[points.Length];for(int i=0;i<points.Length;i++){var p=points[i];var key=new Vector3Int(Mathf.RoundToInt(p.x*cells),Mathf.RoundToInt(p.y*cells),Mathf.RoundToInt(p.z*cells));if(!map.TryGetValue(key,out int index)){index=vertices.Count;map[key]=index;vertices.Add(p);}remap[i]=index;}var triangles=new List<int>();var seen=new HashSet<string>();for(int i=0;i<source.Length;i+=3){int a=remap[source[i]],b=remap[source[i+1]],c=remap[source[i+2]];if(a==b||b==c||c==a)continue;var sorted=new[]{a,b,c}.OrderBy(v=>v).ToArray();string k=sorted[0]+"_"+sorted[1]+"_"+sorted[2];if(!seen.Add(k))continue;triangles.AddRange(new[]{a,b,c});}var mesh=new Mesh{name=name};mesh.SetVertices(vertices);mesh.SetTriangles(triangles,0);mesh.SetUVs(0,vertices.Select(v=>new Vector2(v.x*1.3f,v.y*1.3f+v.z*.4f)).ToList());mesh.RecalculateNormals();mesh.RecalculateBounds();return mesh;}
static void Run(){var log=new StringBuilder();try{rng=new System.Random(7341);Directory.CreateDirectory(Dir);var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=scene.GetRootGameObjects().Single(g=>g.name=="Coastal Rocky Terrain");var terrain=root.GetComponentInChildren<Terrain>();var old=root.transform.Find("Mountain rock and vegetation details");if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);var detail=new GameObject("Mountain rock and vegetation details");detail.transform.SetParent(root.transform,false);
ConfigureAtlas();var grass=AssetDatabase.LoadAssetAtPath<Texture2D>(Dir+"/Mountain Foliage Atlas.png");var rockTexture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Scenes/Oasis/CoastalTerrain/Seamless Coastal Grey Rock.png");var materials=new Dictionary<string,Material>{{"Rock",Mat("Shared mountain boulder",new Color(1.08f,1.04f,.92f),rockTexture)},{"Pine",Foliage("Shared mountain pine",new Color(.9f,1,.86f),grass)},{"Shrub",Foliage("Shared mountain shrub",new Color(1,1,.91f),grass)},{"Trunk",Mat("Shared mountain bark",new Color(.25f,.17f,.10f),null)}};
var nearP=new Mesh[3];var farP=new Mesh[3];var nearS=new Mesh[3];var farS=new Mesh[3];for(int i=0;i<3;i++){nearP[i]=SaveMesh(Pine(false,i),Dir+"/Pine "+i+".asset");farP[i]=SaveMesh(Pine(true,i),Dir+"/Pine "+i+" distant.asset");nearS[i]=SaveMesh(Shrub(false,i),Dir+"/Shrub "+i+".asset");farS[i]=SaveMesh(Shrub(true,i),Dir+"/Shrub "+i+" distant.asset");}
var trunk=SaveMesh(Trunk(),Dir+"/Pine trunk.asset");var rocks=new List<Mesh>();var farRocks=new List<Mesh>();for(int i=1;i<=6;i++){if(i==4||i==6)continue;var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Scenes/Oasis/Art/Environment/Prefabs/Rock_0"+i+"_Prefab.prefab");var filter=prefab.GetComponentInChildren<MeshFilter>();var data=typeof(FinalPNGCityDetails).GetMethod("Read",F).Invoke(null,new object[]{filter.sharedMesh});var points=(Vector3[])data.GetType().GetField("p").GetValue(data);var ids=(int[])data.GetType().GetField("ids").GetValue(data);var uv=(Vector2[][])data.GetType().GetField("uv").GetValue(data);var b=filter.sharedMesh.bounds;var m=new Mesh{name="Shared mountain rock "+i,indexFormat=IndexFormat.UInt32};float extent=Mathf.Max(b.size.x,Mathf.Max(b.size.y,b.size.z));m.vertices=points.Select(p=>(p-b.center)/extent*2).ToArray();m.triangles=ids;m.uv=uv[0];m.RecalculateNormals();m.RecalculateBounds();var nearRock=Cluster(m,4,"Mobile boulder "+i);var farRock=Cluster(m,2,"Distant boulder "+i);rocks.Add(SaveMesh(nearRock,Dir+"/Boulder "+i+".asset"));farRocks.Add(SaveMesh(farRock,Dir+"/Boulder "+i+" distant.asset"));UnityEngine.Object.DestroyImmediate(m);log.AppendLine("Rock "+i+" reduced triangles: "+rocks.Last().triangles.Length/3+" distant: "+farRocks.Last().triangles.Length/3);}
var batches=new Dictionary<string,Batch>();int nr=0,np=0,ns=0;var pos=terrain.transform.position;var size=terrain.terrainData.size;var boundary=File.ReadAllLines("FinalEnvironmentRoadReview/CoastalSnappedEdge.txt").Select(s=>{var a=s.Trim('(',')').Split(',');return new Vector2(float.Parse(a[0],System.Globalization.CultureInfo.InvariantCulture),float.Parse(a[1],System.Globalization.CultureInfo.InvariantCulture));}).ToArray();
for(float z=pos.z+2;z<pos.z+size.z-2;z+=5.5f)for(float x=pos.x+2;x<pos.x+size.x-2;x+=5.5f){float wx=x+R(-1.7f,1.7f),wz=z+R(-1.7f,1.7f);float u=(wx-pos.x)/size.x,v=(wz-pos.z)/size.z;if(terrain.terrainData.IsHole(Mathf.FloorToInt(u*512),Mathf.FloorToInt(v*512)))continue;float distance=float.MaxValue;var point=new Vector2(wx,wz);for(int j=0;j<boundary.Length-1;j++){var e=boundary[j+1]-boundary[j];var q=boundary[j]+e*Mathf.Clamp01(Vector2.Dot(point-boundary[j],e)/e.sqrMagnitude);distance=Mathf.Min(distance,Vector2.Distance(point,q));}if(distance<4.5f||distance>40)continue;float height=terrain.SampleHeight(new Vector3(wx,0,wz));float slope=terrain.terrainData.GetSteepness(u,v);int cx=Mathf.FloorToInt(wx/65),cz=Mathf.FloorToInt(wz/65);float choice=R(0,1);float yaw=R(0,360);if(choice<.36f){int rockIndex=rng.Next(rocks.Count);var mesh=rocks[rockIndex];float scale=R(1.6f,4.4f);if(distance<9)scale=Mathf.Min(scale,2);var matrix=Matrix4x4.TRS(new Vector3(wx,height-scale*.32f,wz),Quaternion.Euler(R(-15,15),yaw,R(-15,15)),new Vector3(scale*R(.8f,1.4f),scale*R(.65f,1.1f),scale));Add(batches,"Rock",cx,cz,mesh,farRocks[rockIndex],matrix);nr++;}else if(choice<.57f&&slope<53&&distance>8){int variant=rng.Next(3);float scale=R(.65f,1.35f);var matrix=Matrix4x4.TRS(new Vector3(wx,height-.25f,wz),Quaternion.Euler(0,yaw,0),Vector3.one*scale);Add(batches,"Pine",cx,cz,nearP[variant],farP[variant],matrix);np++;}else if(choice<.92f&&slope<68){int variant=rng.Next(3);float scale=R(.7f,1.65f);var matrix=Matrix4x4.TRS(new Vector3(wx,height-.25f,wz),Quaternion.Euler(0,yaw,0),Vector3.one*scale);Add(batches,"Shrub",cx,cz,nearS[variant],farS[variant],matrix);ns++;}}
long nearTriangles=0,farTriangles=0;foreach(var item in batches){var g=new GameObject(item.Key);g.transform.SetParent(detail.transform,false);string type=item.Key.Split('_')[0];var near=SaveMesh(Combined(item.Value.near,item.Key+" near"),Dir+"/"+item.Key+" near.asset");var far=SaveMesh(Combined(item.Value.far,item.Key+" distant"),Dir+"/"+item.Key+" distant.asset");nearTriangles+=near.triangles.Length/3;farTriangles+=far.triangles.Length/3;var r0=Child(g,"Detailed",near,materials[type]);var r1=Child(g,"Distant",far,materials[type]);var lod=g.AddComponent<LODGroup>();lod.fadeMode=LODFadeMode.None;lod.SetLODs(new[]{new LOD(.11f,new[]{r0}),new LOD(.014f,new[]{r1})});lod.RecalculateBounds();}
for(int i=0;i<3;i++){var template=new GameObject("Mountain Pine "+i);Child(template,"Foliage",nearP[i],materials["Pine"]);PrefabUtility.SaveAsPrefabAsset(template,Dir+"/Mountain Pine "+i+".prefab");UnityEngine.Object.DestroyImmediate(template);var shrub=new GameObject("Mountain Shrub "+i);Child(shrub,"Foliage",nearS[i],materials["Shrub"]);PrefabUtility.SaveAsPrefabAsset(shrub,Dir+"/Mountain Shrub "+i+".prefab");UnityEngine.Object.DestroyImmediate(shrub);}
PrefabUtility.SaveAsPrefabAssetAndConnect(root,"Assets/Scenes/Oasis/CoastalTerrain/Coastal Rocky Terrain.prefab",InteractionMode.AutomatedAction);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
typeof(FinalPNGCityDetails).GetMethod("Capture",F).Invoke(null,new object[]{scene,new Vector3(813,31,150),new Vector3(819,35,350),"Detailed-Mountain-Road-Level"});typeof(FinalPNGCityDetails).GetMethod("Capture",F).Invoke(null,new object[]{scene,new Vector3(914,100,305),new Vector3(864,40,250),"Detailed-Mountain-Overview"});
log.AppendLine("SUCCESS rocks="+nr+" pines="+np+" shrubs="+ns+"; 65m spatial chunks="+batches.Count+"; 3 shared instanced materials; one streamed ASTC foliage atlas with alpha cutoff and coverage-preserving mipmaps; near triangles="+nearTriangles+" far triangles="+farTriangles+"; two mesh LODs with distant culling; no added colliders; boundary clearance >=4.5m; native terrain and original roads retained.");}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/CoastalMountainDetailsReport.txt",log.ToString());}}
